package org.kanger;
import java.util.*;
import org.kanger.ContextProductionCapture.Source;
import org.kanger.ContextProductionCapture.Support;
import org.kanger.ContextProductionCapture.Clause;
import org.kanger.ContextProductionNativeBinding.Entry;
import org.kanger.ContextProductionNativeBinding.Snapshot;
import org.kanger.ContextWitnessResultTransport.*;
import org.kanger.ContextRelationalInterpretation.*;
import org.kanger.ContextUniversalInputResiduals.Residual;
/** Bounded candidates only. Separate original and actual-final audit receipts are mandatory. */
final class ContextSignedRelationalModelSearch {
 enum Kind { COMMON,PRIVATE,UNIT,COMPOUND,TERMINAL }
 static final class Row {final Snapshot cut,member;final Entry entry;Row(Snapshot cut,Snapshot member,Entry entry){this.cut=cut;this.member=member;this.entry=entry;}}
 static final class Obligation {final Kind kind;final Cut cut;final Object carrier;final Support support;Obligation(Kind kind,Cut cut,Object carrier,Support support){this.kind=kind;this.cut=cut;this.carrier=carrier;this.support=support;}}
 static final class Ledger {
  final ContextSignedWitnessNativeBranch.Receipt branch;final ContextSignedUnaryModelSearch.Policy policy;final Map<Cut,ContextRelationalInterpretation> models;final List<Row> rows;final List<Obligation> obligations;
  Ledger(ContextSignedWitnessNativeBranch.Receipt branch,ContextSignedUnaryModelSearch.Policy policy,Map<Cut,ContextRelationalInterpretation> models,List<Row> rows,List<Obligation> obligations){this.branch=branch;this.policy=policy;this.models=Collections.unmodifiableMap(new LinkedHashMap<>(models));this.rows=Collections.unmodifiableList(new ArrayList<>(rows));this.obligations=Collections.unmodifiableList(new ArrayList<>(obligations));}
 }
 static final class Result {final int tried,originals,originalRows,finalObligations;final String reason;final ContextSignedRelationalModelAudit.FinalReceipt output;Result(int tried,int originals,String reason,ContextSignedRelationalModelAudit.FinalReceipt output){this.tried=tried;this.originals=originals;this.reason=reason;this.output=output;originalRows=output==null?0:output.ledger.rows.size();finalObligations=output==null?0:output.ledger.obligations.size();}}
 static final class Data {final Cut cut;final Set<Signature> signatures=new LinkedHashSet<>();final Set<Source> witnesses=new LinkedHashSet<>();final Set<Origin> origins=new LinkedHashSet<>();Data(Cut cut){this.cut=cut;}}
 static final class Choice {final Data data;final Signature signature;final List<Integer> tuple;final Source witness;final Origin origin;final int radix;Choice(Data d,Signature s,List<Integer> t,Source w,Origin o,int radix){data=d;signature=s;tuple=t;witness=w;origin=o;this.radix=radix;}}
 static Residual residual(Obligation o){switch(o.kind){case UNIT:return ((ContextUniversalSignedUnitExchange.Unit)o.carrier).clause;case COMPOUND:return ((ContextUniversalCompoundExchange.ResidualProof)o.carrier).clause;case TERMINAL:return ((ContextUniversalFrozenConstraints.Proof)o.carrier).clause;default:throw new IllegalStateException("Residual obligation required");}}
 static boolean required(ContextSignedWitnessNativeBranch.Receipt b){for(Row r:rows(b)){if(r.entry.bundle!=null){for(ContextWitnessBundle.Atom a:r.entry.bundle.atoms)if(a.arguments.size()!=1)return true;}else for(Clause c:r.entry.clauses){if(c.variables.size()>3)return true;for(org.kanger.ContextProductionCapture.Atom a:c.literals)if(a.arguments.size()!=1)return true;}}ContextSignedWitnessStop.Receipt stop=b.termination.result.stopping;ContextSignedWitnessContinuationScope.Receipt scope=b.termination.result.output;for(ContextUniversalSignedUnitExchange.Unit u:stop.units.units)if(general(u.clause))return true;for(ContextUniversalCompoundExchange.ResidualProof r:stop.compounds.clauses)if(general(r.clause))return true;for(ContextUniversalFrozenConstraints.Result check:stop.terminal.checks.values())for(ContextUniversalFrozenConstraints.Proof p:check.proofs)if(general(p.clause))return true;return false;}
 private static boolean general(Residual c){if(c.variables.size()>3)return true;for(org.kanger.ContextUniversalInputResiduals.Literal a:c.literals)if(a.arguments.size()!=1)return true;return false;}
 private static List<Row> rows(ContextSignedWitnessNativeBranch.Receipt b){List<Row> rows=new ArrayList<>();List<Snapshot> cuts=new ArrayList<>();cuts.add(b.x);cuts.addAll(b.foreign);for(Snapshot c:cuts)for(Snapshot m:c.physicalMembers())for(Entry e:m.primary)rows.add(new Row(c,m,e));return rows;}
 private static void add(List<Obligation> out,Kind k,Cut cut,Object carrier,Support s,ContextSignedUnaryModelSearch.Policy p,Runnable w){w.run();if(out.size()>=p.extension.audit.obligations)throw new IllegalStateException("Relational final obligation bound");out.add(new Obligation(k,cut,carrier,s));}
 static List<Obligation> obligations(ContextSignedWitnessNativeBranch.Receipt b,ContextSignedUnaryModelSearch.Policy p,Runnable w){List<Obligation> out=new ArrayList<>();ContextSignedWitnessStop.Receipt stop=b.termination.result.stopping;ContextSignedWitnessContinuationScope.Receipt scope=b.termination.result.output;for(Cut c:stop.terminal.checks.keySet()){for(Item i:scope.current().packet.items)for(Support s:i.proofs)add(out,Kind.COMMON,c,i,s,p,w);PrivatePool pool=scope.current().privatePools.get(c);if(pool!=null)for(Item i:pool.local.items)for(Support s:i.proofs)add(out,Kind.PRIVATE,c,i,s,p,w);for(ContextUniversalSignedUnitExchange.Unit u:stop.units.units)add(out,Kind.UNIT,c,u,u.support,p,w);for(ContextUniversalCompoundExchange.ResidualProof r:stop.compounds.clauses)add(out,Kind.COMPOUND,c,r,r.support,p,w);for(ContextUniversalFrozenConstraints.Proof r:stop.terminal.checks.get(c).proofs)add(out,Kind.TERMINAL,c,r,r.support,p,w);}return out;}
 private static void original(Data d,Entry e,Runnable w){w.run();if(e.bundle!=null){if(e.bundle.witnesses!=1)throw new IllegalStateException("One-binder relational bundle profile");d.witnesses.add(e.source);for(ContextWitnessBundle.Atom a:e.bundle.atoms){ContextArgumentBudget.positions(a.arguments,w);d.signatures.add(new Signature(a.predicate,a.arguments.size()));}}else for(Clause c:e.clauses)for(org.kanger.ContextProductionCapture.Atom a:c.literals){ContextArgumentBudget.positions(a.arguments,w);d.signatures.add(new Signature(a.predicate,a.arguments.size()));}}
 private static void conclusion(Data d,Obligation o,Runnable w){w.run();if(o.kind==Kind.COMMON||o.kind==Kind.PRIVATE){Item i=(Item)o.carrier;d.signatures.add(new Signature(i.atom.predicate,i.atom.arguments.size()));for(Slot s:i.atom.arguments){w.run();if(s.origin!=null)d.origins.add(s.origin);}}else for(org.kanger.ContextUniversalInputResiduals.Literal a:residual(o).literals){d.signatures.add(new Signature(a.predicate,a.arguments.size()));for(org.kanger.ContextUniversalInputResiduals.Term t:a.arguments){w.run();if(t.origin!=null)d.origins.add(t.origin);}}}
 private static boolean next(List<Choice> choices,int[] digits,Runnable w){for(int i=0;i<digits.length;i++){w.run();if(++digits[i]<choices.get(i).radix)return true;digits[i]=0;}return false;}
 private static Map<Cut,ContextRelationalInterpretation> candidate(List<Data> data,List<SemanticTermSnapshot> points,List<Choice> choices,int[] digits,boolean dense,Runnable w){Map<Cut,ContextRelationalInterpretation> out=new LinkedHashMap<>();for(Data d:data){Map<Source,Integer> witnesses=new LinkedHashMap<>();Map<Origin,Integer> origins=new LinkedHashMap<>();Map<Signature,Map<List<Integer>,Boolean>> entries=new LinkedHashMap<>();Map<Signature,Boolean> defaults=new LinkedHashMap<>();for(Signature s:d.signatures){w.run();entries.put(s,new LinkedHashMap<>());defaults.put(s,false);}for(int i=0;i<choices.size();i++){w.run();Choice c=choices.get(i);if(c.data!=d)continue;if(c.witness!=null)witnesses.put(c.witness,digits[i]);else if(c.origin!=null)origins.put(c.origin,digits[i]);else if(dense){if(digits[i]!=0)entries.get(c.signature).put(c.tuple,true);}else defaults.put(c.signature,digits[i]!=0);}for(Origin o:d.origins){w.run();if(d.witnesses.contains(o.source))origins.put(o,witnesses.get(o.source));}Map<Signature,Table> tables=new LinkedHashMap<>();for(Signature s:d.signatures)tables.put(s,new Table(defaults.get(s),entries.get(s)));out.put(d.cut,new ContextRelationalInterpretation(points,tables,witnesses,origins));}return out;}
 private static List<Choice> choices(List<Data> data,List<SemanticTermSnapshot> points,boolean dense,ContextSignedUnaryModelSearch.Policy p,Runnable w){List<Choice> choices=new ArrayList<>();int witnessCount=0,imported=0,cells=0;for(Data d:data){for(Source s:d.witnesses){w.run();if(++witnessCount>p.witnesses)throw new IllegalStateException("Relational Source witness choice bound");choices.add(new Choice(d,null,null,s,null,points.size()));}for(Origin o:d.origins)if(!d.witnesses.contains(o.source)){w.run();if(++imported>p.extension.origins)throw new IllegalStateException("Relational imported Origin bound");choices.add(new Choice(d,null,null,null,o,points.size()));}}
  for(Data d:data)for(Signature s:d.signatures){w.run();int count=1;if(dense){for(int pos=0;pos<s.arity;pos++){w.run();if(count>(p.cells-cells)/(points.size()+1))throw new IllegalStateException("Tuple Cartesian cells exceed search budget BEFORE allocation");count*=points.size()+1;}}if(count>p.cells-cells)throw new IllegalStateException("Relational truth cell bound");cells+=count;if(!dense)choices.add(new Choice(d,s,null,null,null,2));else{int[] tuple=new int[s.arity];for(int row=0;row<count;row++){w.run();List<Integer> key=new ArrayList<>();for(int v:tuple){w.run();key.add(v);}choices.add(new Choice(d,s,Collections.unmodifiableList(key),null,null,2));for(int pos=tuple.length-1;pos>=0;pos--){w.run();if(++tuple[pos]<=points.size())break;tuple[pos]=0;}}}}
  return choices;
 }
 private static int fixed(ContextRelationalInterpretation m,SemanticTermSnapshot value,Runnable w){for(int i=0;i<m.points.size();i++){w.run();if(m.points.get(i).semanticallyEquals(value))return i;}throw new IllegalStateException("Actual ground constant absent from basis");}
 private static void demand(Map<Signature,Map<List<Integer>,Boolean>> demands,String name,List<Integer> tuple,boolean positive,Runnable w){ContextArgumentBudget.positions(tuple,w);Signature signature=new Signature(name,tuple.size());Map<List<Integer>,Boolean> table=demands.computeIfAbsent(signature,k->new LinkedHashMap<>());Boolean old=table.put(tuple,positive);if(old!=null&&old!=positive)throw new IllegalStateException("Chosen denotation has conflicting tuple demands; not a theory refutation");}
 private static Map<Cut,ContextRelationalInterpretation> grounded(Map<Cut,ContextRelationalInterpretation> models,ContextSignedWitnessNativeBranch.Receipt branch,List<Row> rows,List<Obligation> obligations,ContextSignedUnaryModelSearch.Policy p,Runnable w){Map<Cut,ContextRelationalInterpretation> out=new LinkedHashMap<>();int stored=0;for(Map.Entry<Cut,ContextRelationalInterpretation> pair:models.entrySet()){Cut cut=pair.getKey();ContextRelationalInterpretation m=pair.getValue();Map<Signature,Map<List<Integer>,Boolean>> demands=new LinkedHashMap<>();
  for(Row row:rows)if(row.cut==branch.x||Cut.of(row.cut).equals(cut)){Entry e=row.entry;w.run();if(e.bundle!=null){for(ContextWitnessBundle.Atom a:e.bundle.atoms){List<Integer> tuple=new ArrayList<>();for(ContextWitnessBundle.Slot t:a.arguments){w.run();tuple.add(t.witness>=0?m.witnesses.get(e.source):fixed(m,t.value,w));}demand(demands,a.predicate,tuple,a.positive,w);}}else for(Clause c:e.clauses)if(c.literals.size()==1&&c.variables.isEmpty()){org.kanger.ContextProductionCapture.Atom a=c.literals.get(0);List<Integer> tuple=new ArrayList<>();for(org.kanger.ContextProductionCapture.Slot t:a.arguments){w.run();tuple.add(fixed(m,t.value,w));}demand(demands,a.predicate,tuple,a.positive,w);}}
  for(Obligation o:obligations)if(o.cut.equals(cut)){w.run();if(o.kind==Kind.COMMON||o.kind==Kind.PRIVATE){Item item=(Item)o.carrier;List<Integer> tuple=new ArrayList<>();for(Slot t:item.atom.arguments){w.run();tuple.add(t.origin==null?fixed(m,t.value,w):m.denotations.get(t.origin));}demand(demands,item.atom.predicate,tuple,item.atom.positive,w);}else{Residual c=residual(o);if(c.literals.size()==1&&c.variables.isEmpty()){org.kanger.ContextUniversalInputResiduals.Literal a=c.literals.get(0);List<Integer> tuple=new ArrayList<>();for(org.kanger.ContextUniversalInputResiduals.Term t:a.arguments){w.run();tuple.add(t.origin==null?fixed(m,t.value,w):m.denotations.get(t.origin));}demand(demands,a.predicate,tuple,a.positive,w);}}}
  Map<Signature,Table> tables=new LinkedHashMap<>();for(Map.Entry<Signature,Table> relation:m.relations.entrySet()){w.run();if(++stored>p.cells)throw new IllegalStateException("Sparse default/exception storage exceeds cells");boolean otherwise=relation.getValue().otherwise;Map<List<Integer>,Boolean> overrides=new LinkedHashMap<>();Map<List<Integer>,Boolean> required=demands.get(relation.getKey());if(required!=null)for(Map.Entry<List<Integer>,Boolean> fact:required.entrySet()){w.run();if(fact.getValue()!=otherwise){if(++stored>p.cells)throw new IllegalStateException("Sparse default/exception storage exceeds cells");overrides.put(fact.getKey(),fact.getValue());}}tables.put(relation.getKey(),new Table(otherwise,overrides));}out.put(cut,new ContextRelationalInterpretation(m.points,tables,m.witnesses,m.denotations));}return out;}
 static Result run(ContextSignedWitnessNativeBranch.Receipt b,List<SemanticTermSnapshot> points,ContextSignedUnaryModelSearch.Policy p){int tried=0,originals=0;String last="No relational model";
  try{if(b==null||points==null||p==null||b.status!=ContextSignedWitnessNativeBranch.Status.QUIESCENT_SUPPLIED)throw new IllegalArgumentException("Actual completed relational family required");ContextSignedWitnessNativeBranchAudit.check(b,b.x,b.foreign,b.policy,p.extension.audit.work,p.extension.audit.capacity);Runnable w=ContextGroundProductionRounds.budget(p.work);List<Row> rows=rows(b);if(rows.size()>p.original.rows)throw new IllegalStateException("Relational original row bound");List<Obligation> obligations=obligations(b,p,w);Map<Cut,Data> cuts=new LinkedHashMap<>();cuts.put(Cut.of(b.x),new Data(Cut.of(b.x)));for(Snapshot c:b.foreign)cuts.put(Cut.of(c),new Data(Cut.of(c)));for(Data d:cuts.values()){for(Entry e:b.x.primary)original(d,e,w);for(Snapshot c:b.foreign)if(Cut.of(c).equals(d.cut))for(Entry e:c.primary)original(d,e,w);}for(Obligation o:obligations)conclusion(cuts.get(o.cut),o,w);List<Data> data=new ArrayList<>(cuts.values());
   for(int phase=0;phase<3;phase++){boolean dense=phase==2,sparse=phase==1;List<Choice> choices=choices(data,points,dense,p,w);int[] digits=new int[choices.size()];int inPhase=0;while(tried<p.candidates&&(dense||inPhase<Math.min(p.candidates,Math.max(2,p.candidates/3)))){boolean allTrue=!dense&&inPhase==(sparse?0:1);int[] proposed=digits;if(allTrue){proposed=new int[digits.length];for(int i=0;i<proposed.length;i++){w.run();if(choices.get(i).signature!=null)proposed[i]=1;}}tried++;inPhase++;try{Map<Cut,ContextRelationalInterpretation> models=candidate(data,points,choices,proposed,dense,w);if(sparse)models=grounded(models,b,rows,obligations,p,w);Ledger l=new Ledger(b,p,models,rows,obligations);ContextSignedRelationalModelAudit.OriginalReceipt original=ContextSignedRelationalModelAudit.original(l,p.original.work);originals++;ContextSignedRelationalModelAudit.FinalReceipt done=ContextSignedRelationalModelAudit.finalModel(l,original,p.extension.audit.work);return new Result(tried,originals,"Original and ALL actual-final relational obligations independently audited",done);}catch(IllegalStateException rejected){last=rejected.toString();}if(!allTrue&&!next(choices,digits,w))break;}}
   return new Result(tried,originals,"Bounded relational candidates incomplete, not a no-model proof: "+last,null);
  }catch(Exception failure){return new Result(tried,originals,failure.toString(),null);}
 }
}
